SELECT id, region_scope_id, material_code, material_name, unit, population_basis, per_person_per_day, fixed_base_quantity, level_factor, reserve_ratio, package_size, minimum_quantity FROM material_standard WHERE standard_set_id = #{setId} AND situation_level = #{level} AND region_scope_id IN
